import{_ as p,l as r,o as a,c as n,v as o,p as s,x as t,d as l,i as m,S as d}from"./chunks/framework.InCnrqk-.js";const y=JSON.parse('{"title":"带生产的一般均衡","description":"","frontmatter":{"title":"带生产的一般均衡","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/production-economy-ge.md","filePath":"econ/production-economy-ge.md","lastUpdated":1789023840000}'),c={name:"econ/production-economy-ge.md"};function h(u,e,_,E,j,f){const i=r("Mermaid");return a(),n("div",null,[e[1]||(e[1]=o('<h1 id="带生产的一般均衡" tabindex="-1">带生产的一般均衡 <a class="header-anchor" href="#带生产的一般均衡" aria-label="Permalink to &quot;带生产的一般均衡&quot;">​</a></h1><div class="epigraph"><p>厂商在既定价格下选生产计划，利润按股权流回消费者；出清必须同时包括产品与要素，而不只是纯交换的禀赋搬家。</p><footer>—— 据 Debreu, Theory of Value, 1959；Mas-Colell, Whinston and Green 第 16–17 章整理</footer></div><p>定位：<a href="/econ/welfare-theorems">上一课</a>。两定理在纯交换里把均衡与帕累托接好，并声明生产并行：利润最大化时「更好的计划更贵」，第二定理要生产集凸。本课不重证第一定理的会计。缺口是把厂商写进定义：生产集 \\(Y^j\\)、利润分配 \\(\\theta^{ij}\\)、财富不再只是 \\(p\\cdot\\omega^i\\)，市场出清变成 \\(\\sum x^i=\\sum\\omega^i+\\sum y^j\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯交换里总供给是禀赋。有生产之后，净产出 \\(y^j\\in Y^j\\) 可以创造（或消耗）商品，盒的边长不再外生。消费者 \\(i\\) 持有厂商 \\(j\\) 的份额 \\(\\theta^{ij}\\ge 0\\)，\\(\\sum_i\\theta^{ij}=1\\)。给定 \\(p\\)，厂商</p> \\[y^j(p)\\in\\arg\\max_{y\\in Y^j}p\\cdot y,\\qquad \\pi^j(p)=p\\cdot y^j(p), \\]<p>消费者财富 \\(m^i(p)=p\\cdot\\omega^i+\\sum_j\\theta^{ij}\\pi^j(p)\\)，需求 \\(x^i(p)\\) 在预算 \\(p\\cdot x\\le m^i(p)\\) 上最优。均衡还要求 \\(\\sum_i x^i(p)=\\sum_i\\omega^i+\\sum_j y^j(p)\\)（免费处置则不等式）。缺口不是再写一次 \\(z(p)\\) 的符号，而是：<strong>利润从哪来、回到谁身上，要素市场怎样被同一组 \\(p\\) 出清。</strong></p><p><a href="/econ/cost-minimization">成本最小化</a>与<a href="/econ/profit-supply">利润供给</a>已在局部均衡写过单家。这里 \\(w\\) 与 \\(p\\) 是同一价格向量的不同分量，要素不再当参数。</p><h3 id="股权是预算流量-不是控制权" tabindex="-1">股权是预算流量，不是控制权 <a class="header-anchor" href="#股权是预算流量-不是控制权" aria-label="Permalink to &quot;股权是预算流量，不是控制权&quot;">​</a></h3><p>\\(\\theta^{ij}\\) 只分配利润，不影响「把 \\(p\\) 当参数」这一竞争假设。厂商不内部化股东的偏好，只最大化 \\(p\\cdot y\\)——这是第一定理对生产侧成立的关键。若厂商最大化加权股东效用，问题变成另一套目标，本课不走。IRS、非凸 \\(Y^j\\) 让竞争供给对应爆炸或为空，均衡可能不存在；第二定理的分离也失败。那是存在性课的墙，本课先在凸、可歇业的 \\(Y\\) 上把会计钉住。</p><p><span class="marginnote">瓦尔拉斯定律仍成立：把利润加进预算再加总，产出的价值 \\(p\\cdot\\sum y\\) 与利润项对消，剩下 \\(p\\cdot(\\sum x-\\sum\\omega-\\sum y)=0\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>经济 \\(\\bigl((\\succsim^i,\\omega^i,\\theta^i),(Y^j)\\bigr)\\)。均衡是 \\((p^*,x^*,y^*)\\)，使 \\(y^{*j}\\) 利润最大、\\(x^{*i}\\) 在 \\(m^i(p^*)\\) 上需求最大、市场出清。私人所有制定义如上；也可以把 \\(Y\\) 写成总量生产集 \\(Y=\\sum Y^j\\)，对偶上常等价（凸时）。</p><p>有效性：配置 \\((x,y)\\) 可行若 \\(\\sum x\\le\\sum\\omega+\\sum y\\)、\\(y^j\\in Y^j\\)。帕累托对消费者偏好而言，生产只作为可行性。第一定理的证明几乎照搬：更好的消费更贵，更好的生产计划不会更亏，加总戳破出清。第二定理要 \\(Y^j\\) 凸，否则支撑价格下厂商想冲向无穷或拒绝生产有效点。</p>',14)),(a(),s(d,null,{default:t(()=>[m(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E4%BB%B7%E6%A0%BC%20p%22%5D%20--%3E%20FIRM%5B%22y%20%E2%88%88%20argmax%20p%C2%B7Y%22%5D%0A%20%20FIRM%20--%3E%20PI%5B%22%CF%80%20%E6%8C%89%20%CE%B8%20%E6%B5%81%E5%85%A5%20m%E2%81%B1%22%5D%0A%20%20P%20--%3E%20CON%5B%22x%E2%81%B1(p%2C%20m%E2%81%B1)%22%5D%0A%20%20PI%20--%3E%20CON%0A%20%20CON%20--%3E%20CLR%5B%22%CE%A3x%20%3D%20%CE%A3%CF%89%20%2B%20%CE%A3y%22%5D%0A%20%20CLR%20--%3E%20EQ%5B%22%E7%94%9F%E4%BA%A7%E7%BB%8F%E6%B5%8E%E7%9A%84%E7%93%A6%E5%B0%94%E6%8B%89%E6%96%AF%E5%9D%87%E8%A1%A1%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>不要把 \\(y\\) 写成限价簿上的存货；生产计划是净产出向量，没有时间优先。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>价格同时给产品与要素标价：厂商比较 MR（在竞争下就是 \\(p\\)）与要素成本，消费者比较 MRS 与同一 \\(p\\)。内点时 \\(\\mathrm{MRS}=\\mathrm{MRT}=p\\) 的比率，交换有效与生产有效被同一组相对价格焊住——这是两定理在生产经济里的几何。利润分配改变的是谁有购买力，从而在帕累托集上挑哪一点，不改变「均衡有效」本身；这与第二定理的转移是同一类工具，\\(\\theta\\) 的再分配相当于改禀赋。</p><p>歇业：\\(0\\in Y^j\\) 保证 \\(\\pi^j\\ge 0\\)。若短期有沉没，局部均衡的停产规则仍看可变利润；一般均衡把已沉没的资本当成禀赋中的商品，会计要声明时期。本课用 Debreu 的静态生产集，不把短长期再推一遍。</p><p>要素与产品是同一价格向量的不同坐标：劳动带负号进入 \\(y\\)，工资是 \\(p\\) 的对应分量。局部均衡把 \\(w\\) 冻住再画产品市场；这里劳动市场必须同时出清，否则「产品市场的竞争均衡」只是投影。CRS 加自由进入时纯利润为零，财富退回 \\(p\\cdot\\omega\\)，看起来像纯交换，但商品清单里已经包含被生产出来的那一部分——配置仍不是禀赋搬家。</p><p><span class="marginnote">Debreu 的商品可以带日期与地点，生产计划是跨期向量。本课有限维、单一静态时期已经够把利润分配说清；无限维 properness 不在主干。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>劳动供给进入效用时，「要素」与「消费」同一商品的不同符号，定义不改。外部性使 \\(Y^j\\) 依赖他人计划，利润最大化用错了可行集。不完全市场让证券利润与现货生产脱节，GEI 后课再写。也不要用本课重写产业组织的厂商：那里的厂商面对向下需求，不是价格接受的 \\(p\\cdot y\\)。</p><p>后课<a href="/econ/ge-existence">存在性</a>把生产对应与需求对应一起送进角谷。后课默认：竞争生产经济含 \\((Y^j,\\theta^{ij})\\)，财富含利润，出清含净产出。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>厂商利润最大，利润按股权进入消费者预算。</li><li>出清是禀赋加净产出；瓦尔拉斯定律对消利润项后仍成立。</li><li>两定理对凸生产集并行；非凸会拆掉供给对应与第二定理。</li><li>下一课用不动点证明这套对应非空。</li><li>出处：Debreu, <em>Theory of Value</em>；Mas-Colell, Whinston and Green 第 16–17 章。</li></ul>',11))])}const g=p(c,[["render",h]]);export{y as __pageData,g as default};
